import re

_TAG = re.compile(r"<answer>(.*?)</answer>", re.S | re.I)
_DIG = re.compile(r"\d+")
_PURE = re.compile(r"\s*([1-9]\d{0,2})\s*")
LOW, HIGH = 1, 40


def _well_formed(reply):
    if not isinstance(reply, str):
        return False
    tags = _TAG.findall(reply)
    if len(tags) != 1:
        return False
    if len(_DIG.findall(reply)) != 1:
        return False
    m = _PURE.fullmatch(tags[0])
    if not m:
        return False
    n = int(m.group(1))
    return LOW <= n <= HIGH


def tighten(replies, state, reward):
    if reward <= 0:
        return reward
    if not replies:
        return 0.0
    for r in replies:
        if not _well_formed(r):
            return 0.0
    return reward
